//! Owning, writing and checking the generated files.
//!
//! A file is the generator's only when one of its first three lines starts with the
//! marker. Any other existing file at a target path is refused before anything is
//! written. Fragments are never written, created or compared.

use std::path::{Path, PathBuf};

use similar::TextDiff;

use crate::config::Paths;
use crate::error::OutputError;
use crate::plan::MockPlan;
use crate::render::{MARKER, render};

/// Lines of context in a `--check` diff.
const DIFF_CONTEXT: usize = 3;

/// A rendered mock and what is on disk at its path.
#[derive(Clone, Debug)]
pub struct Target {
    pub path: PathBuf,
    pub shown: String,
    pub text: String,
    /// The current bytes, when the file exists. Always marker-owned.
    pub existing: Option<Vec<u8>>,
}

/// What `generate` did to one file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Written {
    Wrote,
    Unchanged,
}

/// What `--check` found for one file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Drift {
    Clean,
    Missing,
    /// The unified diff from disk to the generated text.
    Changed(String),
}

/// Renders a plan and reads its target, refusing a file the generator does not own.
/// # Errors
/// Returns the read or ownership error.
pub fn target(plan: &MockPlan, paths: &Paths) -> Result<Target, OutputError> {
    let shown = paths.show(&plan.path);
    let existing = read_existing(&plan.path, &shown)?;
    Ok(Target {
        path: plan.path.clone(),
        shown,
        text: render(plan),
        existing,
    })
}

fn read_existing(path: &Path, shown: &str) -> Result<Option<Vec<u8>>, OutputError> {
    if !path.exists() {
        return Ok(None);
    }
    let bytes = std::fs::read(path).map_err(|source| OutputError::Read {
        path: shown.to_owned(),
        source,
    })?;
    if owned(&bytes) {
        Ok(Some(bytes))
    } else {
        Err(OutputError::NotOwned {
            path: shown.to_owned(),
        })
    }
}

/// Whether one of the first three lines starts with the marker, byte for byte.
#[must_use]
pub fn owned(bytes: &[u8]) -> bool {
    bytes
        .split(|byte| *byte == b'\n')
        .take(3)
        .any(|line| line.starts_with(MARKER.as_bytes()))
}

/// Writes the target when its bytes changed, through a temporary file and a rename.
/// # Errors
/// Returns the IO error, with the target's path.
pub fn write(target: &Target) -> Result<Written, OutputError> {
    if target.existing.as_deref() == Some(target.text.as_bytes()) {
        return Ok(Written::Unchanged);
    }
    let failed = |source| OutputError::Write {
        path: target.shown.clone(),
        source,
    };
    let directory = target.path.parent().unwrap_or_else(|| Path::new("."));
    std::fs::create_dir_all(directory).map_err(failed)?;
    let file_name = target
        .path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_default();
    let temporary = directory.join(format!(".{file_name}.{}.tmp", std::process::id()));
    let result = std::fs::write(&temporary, &target.text)
        .and_then(|()| std::fs::rename(&temporary, &target.path));
    if result.is_err() {
        // Best effort: the rename error is the one worth reporting.
        let _ = std::fs::remove_file(&temporary);
    }
    result.map_err(failed)?;
    Ok(Written::Wrote)
}

/// Compares the target with disk without touching it.
#[must_use]
pub fn drift(target: &Target) -> Drift {
    let Some(existing) = &target.existing else {
        return Drift::Missing;
    };
    if existing.as_slice() == target.text.as_bytes() {
        return Drift::Clean;
    }
    let current = String::from_utf8_lossy(existing);
    let diff = TextDiff::from_lines(current.as_ref(), target.text.as_str())
        .unified_diff()
        .context_radius(DIFF_CONTEXT)
        .header(&target.shown, &format!("{} (generated)", target.shown))
        .to_string();
    Drift::Changed(diff)
}

#[cfg(test)]
mod tests {
    use std::time::{Duration, SystemTime};

    use super::{Drift, Target, Written, drift, owned, read_existing, write};
    use crate::error::OutputError;

    fn target(directory: &std::path::Path, existing: Option<&str>) -> Target {
        Target {
            path: directory.join("mocks/MockM.compact"),
            shown: "mocks/MockM.compact".to_owned(),
            text: "// Generated by compact-mock from a/M. Do not edit by hand.\nx\n".to_owned(),
            existing: existing.map(|text| text.as_bytes().to_vec()),
        }
    }

    #[test]
    fn the_marker_counts_on_the_first_three_lines_only() {
        assert!(owned(b"// Generated by compact-mock from a/M.\n"));
        assert!(owned(
            b"// SPDX-License-Identifier: MIT\n\n// Generated by compact-mock\n"
        ));
        assert!(!owned(b"a\nb\nc\n// Generated by compact-mock\n"));
        assert!(!owned(b"// GENERATED by compact-mock (spike)\n"));
        assert!(!owned("\u{feff}// Generated by compact-mock\n".as_bytes()));
    }

    #[test]
    fn identical_bytes_are_left_alone() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let same = target(directory.path(), None);
        let same = Target {
            existing: Some(same.text.as_bytes().to_vec()),
            ..same
        };
        assert_eq!(write(&same).expect("no write needed"), Written::Unchanged);
        assert!(!same.path.exists());
    }

    #[test]
    fn a_write_creates_the_directory_and_leaves_no_temporary_file() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let fresh = target(directory.path(), None);
        assert_eq!(write(&fresh).expect("the write succeeds"), Written::Wrote);
        assert_eq!(
            std::fs::read_to_string(&fresh.path).expect("the file exists"),
            fresh.text
        );
        let entries = std::fs::read_dir(directory.path().join("mocks"))
            .expect("the directory exists")
            .count();
        assert_eq!(entries, 1);
    }

    #[test]
    fn a_failed_write_names_the_target() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        std::fs::write(directory.path().join("mocks"), "a file, not a directory")
            .expect("the blocker is written");
        let error = write(&target(directory.path(), None)).expect_err("the write fails");
        assert_eq!(error.to_string(), "cannot write mocks/MockM.compact");
    }

    #[test]
    fn check_reports_missing_and_changed_files() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        assert_eq!(drift(&target(directory.path(), None)), Drift::Missing);
        let Drift::Changed(diff) = drift(&target(
            directory.path(),
            Some("// Generated by compact-mock from a/M. Do not edit by hand.\ny\n"),
        )) else {
            panic!("the file drifted");
        };
        assert!(diff.contains("-y\n+x\n"), "{diff}");
    }

    #[test]
    fn an_existing_file_is_read_only_when_the_marker_owns_it() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let path = directory.path().join("MockM.compact");
        assert!(matches!(read_existing(&path, "MockM.compact"), Ok(None)));
        std::fs::write(
            &path,
            "// a\n// b\n// Generated by compact-mock from a/M.\n",
        )
        .expect("written");
        assert!(matches!(read_existing(&path, "MockM.compact"), Ok(Some(_))));
        std::fs::write(
            &path,
            "// a\n// b\n// c\n// Generated by compact-mock from a/M.\n",
        )
        .expect("written");
        let error = read_existing(&path, "MockM.compact").expect_err("refused");
        assert!(matches!(error, OutputError::NotOwned { .. }));
        assert_eq!(
            error.to_string(),
            "MockM.compact exists without the compact-mock marker; move or delete it to let compact-mock own it"
        );
    }

    #[test]
    fn an_unchanged_file_keeps_its_modification_time() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let fresh = target(directory.path(), None);
        std::fs::create_dir_all(fresh.path.parent().expect("a parent")).expect("dirs");
        std::fs::write(&fresh.path, &fresh.text).expect("written");
        let old = SystemTime::now() - Duration::from_hours(1);
        std::fs::File::options()
            .write(true)
            .open(&fresh.path)
            .and_then(|file| file.set_modified(old))
            .expect("the time is set");
        let modified = |path: &std::path::Path| {
            std::fs::metadata(path)
                .and_then(|metadata| metadata.modified())
                .expect("a time")
        };
        let before = modified(&fresh.path);
        let same = Target {
            existing: Some(fresh.text.as_bytes().to_vec()),
            ..fresh
        };
        assert_eq!(write(&same).expect("no write needed"), Written::Unchanged);
        assert_eq!(modified(&same.path), before);
    }

    #[test]
    fn a_changed_file_is_replaced_and_no_temporary_file_is_left() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let stale = "// Generated by compact-mock from a/M. Do not edit by hand.\nold\n";
        let changed = target(directory.path(), Some(stale));
        std::fs::create_dir_all(changed.path.parent().expect("a parent")).expect("dirs");
        std::fs::write(&changed.path, stale).expect("written");
        assert_eq!(write(&changed).expect("the write succeeds"), Written::Wrote);
        assert_eq!(
            std::fs::read_to_string(&changed.path).expect("readable"),
            changed.text
        );
        let names: Vec<String> = std::fs::read_dir(directory.path().join("mocks"))
            .expect("the directory exists")
            .map(|entry| {
                entry
                    .expect("an entry")
                    .file_name()
                    .to_string_lossy()
                    .into_owned()
            })
            .collect();
        assert_eq!(names, ["MockM.compact"]);
    }

    #[test]
    fn the_diff_names_both_sides_and_keeps_three_lines_of_context() {
        let lines: Vec<String> = (1..=12).map(|line| format!("line {line}")).collect();
        let generated = format!("{}\n", lines.join("\n"));
        let on_disk = generated.replace("line 6\n", "line six\n");
        let Drift::Changed(diff) = drift(&Target {
            path: "/x/MockM.compact".into(),
            shown: "mocks/MockM.compact".to_owned(),
            text: generated,
            existing: Some(on_disk.into_bytes()),
        }) else {
            panic!("the file drifted");
        };
        assert_eq!(
            diff,
            "--- mocks/MockM.compact\n+++ mocks/MockM.compact (generated)\n@@ -3,7 +3,7 @@\n line 3\n line 4\n line 5\n-line six\n+line 6\n line 7\n line 8\n line 9\n"
        );
    }

    #[test]
    fn crlf_endings_and_a_missing_final_newline_count_as_changed() {
        let directory = tempfile::TempDir::new().expect("a temporary directory");
        let text = "// Generated by compact-mock from a/M. Do not edit by hand.\nx\n";
        for disk in [text.replace('\n', "\r\n"), text.trim_end().to_owned()] {
            assert!(matches!(
                drift(&target(directory.path(), Some(&disk))),
                Drift::Changed(_)
            ));
        }
        assert_eq!(drift(&target(directory.path(), Some(text))), Drift::Clean);
    }
}
